    val desktopPageTransition = com.bilipai.desktop.ui.DesktopOriginalVideoPageTransitionIntent(
        bvid = targetBvid, cid = page.cid, pageIndex = pageIndex,
        requestedQuality = current.currentQuality, audioLang = current.currentAudioLang,
        ignoreSavedProgress = ignoreSavedProgress, previousCid = previousCid,
        original = desktopPageOriginalState, switchGeneration = switchGeneration,
        isGenerationCurrent = { switchGeneration == pageSwitchGeneration },
        currentPageGeneration = { pageSwitchGeneration },
        isPageSwitchPending = { pendingPageSwitchCid != null },
    )
    pageSwitchJob = environment.invocations.launch(context = desktopPageTransition) {
        try {
            val playUrlData = VideoRepository.getPlayUrlDataForPlaybackTransition(
                bvid = targetBvid,
